"""Exact inspected VRE current stock and cash flow; no arithmetic repair."""
import copy,datetime,hashlib,json,pathlib,runpy
B=pathlib.Path('data/initialization-08b-remediation-work')
BODY='d64526bbf7c390a83e783dcd7341edd9e93d346e4001f5dac65b818f69380220'
# Page, item, code, current/prior lexical, printed caption, original caption, numeric row y.
ROWS=[
 (9,'CURRENT_LIABILITIES','310','5,692,662','5,173,857','Current liabilities','Current liabilities',.276),
 (12,'CFO','20','1,555,752','1,937,295','Net cash generated by operating activities','Net cash generated by operating activities',.564),
 (12,'CFI_SUPPORTING','30','(270,896)','424,511','Net cash (used in)/generated by investing activities','Net cash (used in)/generated by investing',.744),
 (13,'CFF_SUPPORTING','40','(11,768)','(11,233)','Net cash used in financing activities','Net cash used in financing activities',.267),
 (13,'NET_CASH_CHANGE_SUPPORTING','50','1,273,088','2,350,573','Net increases in cash (50=20+30+40)','Net increases in cash (50=20+30+40)',.289),
]
STOCK={'CURRENT_LIABILITIES'}

def validate(c,p,r):
 try:
  row=next(x for x in ROWS if x[1]==c['itemId']);n,item,code,lex,prior,caption,raw,y=row
  stock=item in STOCK;kind='INSTANT' if stock else 'YTD';start='2026-06-30' if stock else '2026-01-01'
  if c['ticker']!='VRE' or c['bodyHash']!=BODY or p['bodyHash']!=BODY or c['page']!=n or p['page']!=n or c['sourceRowCode']!=code or c['sourceCaption']!=caption or c['lexicalValue']!=lex or c['verificationLexicalValue']!=lex or c['periodType']!=kind or c['period']['start']!=start or c['period']['end']!='2026-06-30' or c['unit']!='MILLION_CURRENCY' or c['currency']!='VND' or c['scope']!='CONSOLIDATED' or c['comparativeColumn'] is not False or c['independentHumanApproval'] is not None or c['extractionMethod']!=p['engineA'] or p['engineA']!='APPLE_VISION_ACCURATE_IMAGE_OCR' or c['verificationMethod']!='CODEX_ASSISTANT_SOURCE_IMAGE_READING':return False
  ws=[w for w in p['passA'] if lex in w['text'].split() and w['text'].split()[0]==lex and .67<w['x']<.77 and abs(w['y']-y)<.006 and w['confidence']>=.8]
  if len(ws)!=1:return False
  w=ws[0];cy=w['y']+w['height']/2
  d={'layout':'VRE_EXACT_CURRENT_CASHFLOW_IMAGE','currentColumnOrdinal':0,'currentLexical':lex,'comparativeOriginalOcrLexical':prior,'originalSourceWordText':w['text'],'originalCaptionWords':raw}
  if c['sourceImageColumnDefinition']!=d or abs(c['columnX']-w['x'])>=.001 or abs(c['rowY']-cy)>=.001 or r['numeric_value'](lex)!=c['verifiedCanonicalInteger']:return False
  if not any(a['text']==code and .48<a['x']<.59 and abs(a['y']+a['height']/2-cy)<.016 and a['confidence']>=.8 for a in p['passA']):return False
  caption_tolerance=.04 if item=='CURRENT_ASSETS' else .027
  if not any(a['text']==raw and a['x']<.45 and abs(a['y']+a['height']/2-cy)<caption_tolerance and a['confidence']>=.8 for a in p['passA']):return False
  if prior not in w['text'].split() and not any(a['text']==prior and .83<a['x']<.95 and abs(a['y']+a['height']/2-cy)<.012 and a['confidence']>=.8 for a in p['passA']):return False
  suffix={'CFI_SUPPORTING':'activities'}.get(item)
  if suffix and not any(a['text']==suffix and a['x']<.45 and abs(a['y']+a['height']/2-cy)<.027 for a in p['passA']):return False
  text=r['compact'](r['full_text'](p,'passA'))
  return all(r['compact'](a) in text for a in (['Closing balance','Opening balance','Reclassified','30 June 2026','Unit: VND million'] if stock else ['6-month period ended 30 June 2026','Current period','Prior period','Unit: VND million']))
 except (KeyError,TypeError,ValueError,StopIteration):return False
def main():
 r=runpy.run_path('scripts/reconcile-08b-extraction.py');sha=lambda f:hashlib.sha256(f.read_bytes()).hexdigest()
 q=next(q for q in json.loads((B/'qualifications.json').read_text()) if q['bodyHash']==BODY)
 assert sha(B/(BODY+'.pdf'))==BODY and q['accountingBasis']=='VAS' and q['auditStatus']=='REVIEWED' and q['scope']=='CONSOLIDATED' and q['period']['end']=='2026-06-30'
 cells=[];proof_rows=[]
 for n,item,code,lex,prior,caption,raw,y in ROWS:
  f=B/'ocr'/f'{BODY}-p{n}.json';p=json.loads(f.read_text());assert sha(f.with_suffix('.png'))==p['renderSha256'];w=next(w for w in p['passA'] if lex in w['text'].split() and abs(w['y']-y)<.006)
  stock=item in STOCK;period={**q['period'],'start':'2026-06-30' if stock else '2026-01-01','type':'INSTANT' if stock else 'YTD'}
  d={'layout':'VRE_EXACT_CURRENT_CASHFLOW_IMAGE','currentColumnOrdinal':0,'currentLexical':lex,'comparativeOriginalOcrLexical':prior,'originalSourceWordText':w['text'],'originalCaptionWords':raw}
  c={'ticker':'VRE','securityId':q['securityId'],'documentId':q['documentId'],'bodyHash':BODY,'page':n,'itemId':item,'sourceCaption':caption,'captionAlternative':r['fold'](caption),'sourceRowCode':code,'lexicalValue':lex,'verificationLexicalValue':lex,'verifiedCanonicalInteger':r['numeric_value'](lex),'unit':'MILLION_CURRENCY','currency':'VND','scope':'CONSOLIDATED','period':period,'periodType':period['type'],'columnX':w['x'],'rowY':w['y']+w['height']/2,'extractionMethod':p['engineA'],'verificationMethod':'CODEX_ASSISTANT_SOURCE_IMAGE_READING','renderSha256':p['renderSha256'],'sourceImageColumnDefinition':d,'status':'VERIFIED_TRANSCRIPTION_REVIEW_CANDIDATE','comparativeColumn':False,'independentHumanApproval':None,'sourceOcrProofFile':str(f)}
  assert validate(c,p,r),item
  for key,value in [('lexicalValue',prior),('sourceRowCode','999'),('scope','SEPARATE_STANDALONE'),('unit','CURRENCY'),('columnX',.8),('period',{**period,'end':'2026-07-01'})]:
   bad=copy.deepcopy(c);bad[key]=value;assert not validate(bad,p,r),key
  cells.append(c);proof_rows.append({**c,'periodStart':period['start'],'periodEnd':period['end'],'currentLexical':lex,'rowCode':code,'caption':caption})
 proof=B/'vre-current-cashflow-source-image-reader-proof.json'
 proof.write_text(json.dumps({'method':'CODEX_ASSISTANT_SOURCE_IMAGE_READING','recordedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'governanceStatus':'REVIEW_CANDIDATE','independentHumanApproval':None,'actualInspectedPages':[9,12,13],'rows':proof_rows,'limitations':['Pages 9, 12, 13 inspected. Current column and original reader regions retained. Code 40 disambiguates the financing subtotal from identical lease repayment in code 35. Prior amounts are column anchors and are not admitted. No CAPEX or dividend classifications or common equity inferred.']},ensure_ascii=False,indent=2)+'\n')
 for c in cells:c.update(sourceImageProofFile=str(proof),sourcePageEvidenceHashes=[sha(pathlib.Path(c['sourceOcrProofFile'])),sha(proof)])
 out=B/'source-image-verified-cells.json';old=json.loads(out.read_text());old=[c for c in old if not(c['bodyHash']==BODY and c['itemId'] in {x[1] for x in ROWS})];out.write_text(json.dumps(old+cells,ensure_ascii=False,indent=2)+'\n')
 print(json.dumps({'ticker':'VRE','currentCashflowAndStockCells':len(cells),'negativeControls':30}))
if __name__=='__main__':main()
